style.css:
/* Eye Comfort - warm dark, low blue */
/* i really want this to be global */

html, body {
  background-color: #1e1d1a !important;
  color: #d9d1c3 !important;
}

body {
  line-height: 1.65 !important;
}

body div, body section, body article, body main, body header, body footer, body nav, body aside, body span, body p, body li, body ul, body ol, body td, body tr, body table, body label, body blockquote {
  background-color: transparent !important;
  color: #d9d1c3 !important;
  border-color: #3f3c36 !important;
}

body h1, body h2, body h3, body h4, body h5, body h6 {
  color: #e8e0d2 !important;
}

body a {
  color: #c9a882 !important;
}

body a:visited {
  color: #b39378 !important;
}

body a:hover {
  color: #e0c49a !important;
}

body th {
  background-color: #26251f !important;
  color: #e8e0d2 !important;
}

body input, body textarea, body select, body button {
  background-color: #2a2824 !important;
  color: #d9d1c3 !important;
  border-color: #4a453c !important;
}

body pre, body code {
  background-color: #25231f !important;
  color: #d0c8ba !important;
}

img, video {
  filter: brightness(0.9);
}
